        subtitle: 'La Mecque',
        body: "Le Prophète Muhammad ﷺ naquit à La Mecque le douzième de Rabi' Al-Awwal, l'Année de l'Éléphant — l'année où Allah détruisit Abraha et son armée venus démolir la Ka'bah. Son père Abdullah était décédé avant sa naissance. Sa naissance annonça l'aube d'une ère nouvelle pour l'humanité.",
        quote: "J'étais le premier des Prophètes dans la création et le dernier d'entre eux à être envoyé.",
