        body: "Quraysh imposa un boycott total aux Banu Hashim : ni commerce, ni mariage, ni relations. Ils accrochèrent une charte à la Ka'bah. Le Prophète ﷺ et les musulmans endurèrent trois années difficiles dans la vallée, réduits parfois à manger des feuilles d'arbres.",
