        body: "En une seule et lourde année, le Prophète ﷺ perdit deux piliers de sa vie : son oncle Abu Talib qui le protégeait depuis cinquante ans, et Dame Khadijah qui avait cru en lui quand les autres le rejetaient et l'avait soutenu de ses biens. Il dit : « Allah ne m'a pas remplacée par quelqu'un de meilleur. »",
