        body: "Allah permit à Son Prophète d'émigrer. Les polythéistes se rassemblèrent pour le tuer. Pourtant il ﷺ sortit de parmi eux tandis qu'ils dormaient, en répandant de la terre sur leurs têtes. Il resta trois jours dans la Grotte de Thawr avec Abu Bakr Al-Siddiq. Abu Bakr dit : « Si l'un d'eux regarde à ses pieds, il nous verra. » Il répondit : « Que penses-tu de deux, dont le troisième est Allah ? »",
