/* --- Language Manager --- */
const LangManager = {
  current: 'ar',

  init() {
    const saved = localStorage.getItem('seerah-lang') || 'ar';
    this.set(saved);
  },

  set(lang) {
    if (!TRANSLATIONS[lang]) return;
    this.current = lang;
    localStorage.setItem('seerah-lang', lang);
    document.documentElement.setAttribute('lang', lang);
    document.documentElement.setAttribute('dir', TRANSLATIONS[lang].dir);
    document.body.classList.toggle('rtl', TRANSLATIONS[lang].dir === 'rtl');
    document.body.classList.toggle('ltr', TRANSLATIONS[lang].dir === 'ltr');
    this.applyTranslations();
    document.dispatchEvent(new CustomEvent('langChange', { detail: { lang } }));
  },

  get(key) {
    const t = TRANSLATIONS[this.current];
    return key.split('.').reduce((obj, k) => obj && obj[k], t) || key;
  },

  applyTranslations() {
    document.querySelectorAll('[data-i18n]').forEach(el => {
      const key = el.getAttribute('data-i18n');
      const val = this.get(key);
      if (val && typeof val === 'string') el.textContent = val;
    });
    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
      const key = el.getAttribute('data-i18n-placeholder');
      const val = this.get(key);
      if (val) el.setAttribute('placeholder', val);
    });
    document.querySelectorAll('[data-i18n-html]').forEach(el => {
      const key = el.getAttribute('data-i18n-html');
      const val = this.get(key);
      if (val) el.innerHTML = val;
    });
  },

  t: function(key) { return this.get(key); },
};

window.LangManager = LangManager;
window.TRANSLATIONS = TRANSLATIONS;
